parameters.content:
{
  "ops": [
    {"op": "add-variable", "id": "article", "direction": "in", "type": "string", "description": "Wikipedia article title"},
    {"op": "add-variable", "id": "date1", "direction": "in", "type": "string", "description": "Start date YYYYMMDD"},
    {"op": "add-variable", "id": "date2", "direction": "in", "type": "string", "description": "End date YYYYMMDD"},
    {"op": "add-variable", "id": "result", "direction": "out", "type": "string", "description": "Total views (as string) or Article not found"},

    {"op": "add-node", "id": "filterHighViews", "type": "core.action.transform.filter",
     "definitionFile": "/tmp/filter.json",
     "label": "Filter Views > 500",
     "inputs": {
       "collection": "$vars.fetchPageviews1.output.body.items",
       "operations": [
         {
           "id": "op1",
           "type": "filter",
           "config": {
             "operation": "and",
             "filters": [
               {"id": "f1", "field": "views", "condition": "greater_than", "value": 500}
             ]
           }
         }
       ]
     }
    },

    {"op": "add-node", "id": "sumViews", "type": "core.action.script",
     "definitionFile": "/tmp/script_node.json",
     "label": "Sum Filtered Views",
     "inputs": {
       "script": "const items = $vars.filterHighViews.output;\nconst total = items.reduce((sum, item) => sum + item.views, 0);\nreturn { total: total };"
     }
    },

    {"op": "add-node", "id": "endSuccess", "type": "core.control.end",
     "definitionFile": "/tmp/end.json",
     "label": "End - Success",
     "outputs": "none"
    },

    {"op": "add-node", "id": "endNotFound", "type": "core.control.end",
     "definitionFile": "/tmp/end.json",
     "label": "End - Not Found",
     "outputs": "none"
    },

    {"op": "add-edge", "source": "start", "sourcePort": "output", "target": "fetchPageviews1", "targetPort": "input"},
    {"op": "add-edge", "source": "fetchPageviews1", "sourcePort": "default", "target": "filterHighViews", "targetPort": "input"},
    {"op": "add-edge", "source": "fetchPageviews1", "sourcePort": "error", "target": "endNotFound", "targetPort": "input"},
    {"op": "add-edge", "source": "filterHighViews", "sourcePort": "output", "target": "sumViews", "targetPort": "input"},
    {"op": "add-edge", "source": "sumViews", "sourcePort": "success", "target": "endSuccess", "targetPort": "input"},

    {"op": "add-output-mapping", "endNode": "endSuccess", "var": "result", "source": "=js:String($vars.sumViews.output.total)"},
    {"op": "add-output-mapping", "endNode": "endNotFound", "var": "result", "source": "=js:'Article not found'"}
  ]
}

